mapper.select:
select
	cpdv_llave as  llaveTabla
from pedidoventa_pdvp pp 
	left join account.comprobante_cmp cc on cc.ccmp_documento = pp.cpdv_llave and cc.ccmp_estado = 'A'
where pp.cpdv_plantilla = #{pTemplateId}
	and pp.cpdv_estado != 'I'
	and pp.dpdv_fecha >= #{pStartDate}
	and pp.dpdv_fecha  <  #{pEndDate}
	and cc.ccmp_llave is null
order by pp.dpdv_fecha desc
